using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateWithSeedData(string? dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        private static void SeedData(SchoolContext context)
        {
            var instructor1 = new Instructor
            {
                ID = 1,
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = new DateTime(2020, 1, 15),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 1, Location = "Room 101" }
            };
            var instructor2 = new Instructor
            {
                ID = 2,
                LastName = "Jones",
                FirstMidName = "Jane",
                HireDate = new DateTime(2019, 8, 1),
                CourseAssignments = new List<CourseAssignment>()
            };

            context.Instructors.AddRange(instructor1, instructor2);

            var dept1 = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 100000m,
                StartDate = new DateTime(2020, 9, 1),
                InstructorID = 1
            };
            var dept2 = new Department
            {
                DepartmentID = 2,
                Name = "Mathematics",
                Budget = 75000m,
                StartDate = new DateTime(2019, 9, 1),
                InstructorID = 2
            };

            context.Departments.AddRange(dept1, dept2);

            var course1 = new Course
            {
                CourseID = 1001,
                Title = "Intro to CS",
                Credits = 3,
                DepartmentID = 1,
                Department = dept1,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            var course2 = new Course
            {
                CourseID = 1002,
                Title = "Calculus",
                Credits = 4,
                DepartmentID = 2,
                Department = dept2,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };

            context.Courses.AddRange(course1, course2);

            var student1 = new Student
            {
                ID = 10,
                LastName = "Doe",
                FirstMidName = "Alice",
                EnrollmentDate = new DateTime(2021, 9, 1),
                Enrollments = new List<Enrollment>()
            };
            var student2 = new Student
            {
                ID = 11,
                LastName = "Brown",
                FirstMidName = "Bob",
                EnrollmentDate = new DateTime(2022, 1, 15),
                Enrollments = new List<Enrollment>()
            };
            var student3 = new Student
            {
                ID = 12,
                LastName = "Adams",
                FirstMidName = "Charlie",
                EnrollmentDate = new DateTime(2020, 9, 1),
                Enrollments = new List<Enrollment>()
            };

            context.Students.AddRange(student1, student2, student3);

            var enrollment1 = new Enrollment { EnrollmentID = 1, CourseID = 1001, StudentID = 10, Grade = Grade.A, Course = course1 };
            var enrollment2 = new Enrollment { EnrollmentID = 2, CourseID = 1002, StudentID = 10, Grade = Grade.B, Course = course2 };

            context.Enrollments.AddRange(enrollment1, enrollment2);
            student1.Enrollments.Add(enrollment1);
            student1.Enrollments.Add(enrollment2);

            // Course assignments
            var ca1 = new CourseAssignment { InstructorID = 1, CourseID = 1001, Instructor = instructor1, Course = course1 };
            context.CourseAssignments.Add(ca1);
            instructor1.CourseAssignments.Add(ca1);
            course1.CourseAssignments.Add(ca1);

            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain any pre-existing notifications from static queue
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_ValidInput_EnqueuesNotification()
        {
            _sut.SendNotification("Student", "1", "Alice Doe", EntityOperation.CREATE, "Admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("Student", result.EntityType);
            Assert.Equal("1", result.EntityId);
            Assert.Equal("CREATE", result.Operation);
            Assert.Contains("Alice Doe", result.Message);
            Assert.Equal("Admin", result.CreatedBy);
            Assert.False(result.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityId()
        {
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE);

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains("ID: 42", result.Message);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            _sut.SendNotification("Department", "5", "Math", EntityOperation.DELETE, null);

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("System", result.CreatedBy);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "has been created")]
        [InlineData(EntityOperation.UPDATE, "has been updated")]
        [InlineData(EntityOperation.DELETE, "has been deleted")]
        public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedFragment)
        {
            _sut.SendNotification("Student", "1", "Test Student", operation, "User");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains(expectedFragment, result.Message);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();
            Assert.Null(result);
        }

        [Fact]
        public void SendAndReceive_MultipleNotifications_ReceivesInOrder()
        {
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();
            var third = _sut.ReceiveNotification();

            Assert.Equal("A", first!.EntityType);
            Assert.Equal("B", second!.EntityType);
            Assert.Equal("C", third!.EntityType);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op in the in-memory implementation
            var ex = Record.Exception(() => _sut.MarkAsRead(999));
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_WithDisplayName_IncludesNameInMessage()
        {
            _sut.SendNotification("Course", "100", "Physics 101", EntityOperation.CREATE, "Admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains("Physics 101", result.Message);
            Assert.DoesNotContain("ID: 100", result.Message);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            var before = DateTime.Now;
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);
            var after = DateTime.Now;

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.InRange(result.CreatedAt, before, after);
        }
    }
}

using Xunit;

namespace ContosoUniversity.Tests.Helpers
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_FirstPage_ReturnsCorrectItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void Create_MiddlePage_HasBothNavigation()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.True(result.HasPreviousPage);
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void Create_LastPage_HasOnlyPreviousPage()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 3, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(3, result.PageIndex);
            Assert.True(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_SinglePage_NoNavigation()
        {
            var source = Enumerable.Range(1, 5).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Constructor_SetsPropertiesCorrectly()
        {
            var items = new List<string> { "a", "b", "c" };

            var result = new PaginatedList<string>(items, 15, 2, 5);

            Assert.Equal(3, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
        }
    }
}

