using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_ReturnsLastNameCommaFirstName()
        {
            var student = new Student { LastName = "Doe", FirstMidName = "Jane" };

            Assert.Equal("Doe, Jane", student.FullName);
        }

        [Theory]
        [InlineData("Smith", "John", "Smith, John")]
        [InlineData("O'Brien", "Mary", "O'Brien, Mary")]
        public void FullName_VariousNames_FormatsCorrectly(string last, string first, string expected)
        {
            var instructor = new Instructor { LastName = last, FirstMidName = first };
            Assert.Equal(expected, instructor.FullName);
        }
    }
}

